export function getWordsByCategory(category: ParetoCategory): ParetoWord[] {
  return PARETO_VOCAB.filter(w => w.category === category);
}

export function getWordsByScene(scene: string): ParetoWord[] {
  return PARETO_VOCAB.filter(w => w.scene === scene);
}

export function getTopWords(limit: number = 100): ParetoWord[] {
  return [...PARETO_VOCAB].sort((a, b) => b.frequency - a.frequency).slice(0, limit);
}

export function searchWords(query: string): ParetoWord[] {
  const q = query.toLowerCase();
  return PARETO_VOCAB.filter(w =>
    w.ptBR.toLowerCase().includes(q) ||
    w.enUS.toLowerCase().includes(q) ||
    w.example.toLowerCase().includes(q) ||
    w.examplePt.toLowerCase().includes(q)
  );
}

export const TOTAL_PARETO_WORDS = PARETO_VOCAB.length;

// ─── Randomização (Sistema de Autodesenvolvimento) ────────────────────────────

// Embaralha array usando Fisher-Yates
export function shuffleWords(words: ParetoWord[]): ParetoWord[] {
  const arr = [...words];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Retorna N palavras aleatórias do vocabulário total
export function getRandomWords(count: number = 20): ParetoWord[] {
  return shuffleWords(PARETO_VOCAB).slice(0, count);
}

// Retorna palavras aleatórias por cena, com fallback para palavras gerais
export function getRandomWordsByScene(scene: string, count: number = 12): ParetoWord[] {
  const sceneWords = PARETO_VOCAB.filter(w => w.scene === scene || w.category === (scene as ParetoCategory));
  const pool = sceneWords.length >= count ? sceneWords : PARETO_VOCAB;
  return shuffleWords(pool).slice(0, count);
}

// Retorna palavra aleatória de alta frequência (Pareto top 20%)
export function getDailyWord(): ParetoWord {
  const topWords = [...PARETO_VOCAB]
    .sort((a, b) => b.frequency - a.frequency)
    .slice(0, Math.floor(PARETO_VOCAB.length * 0.2));
  return topWords[Math.floor(Math.random() * topWords.length)];
}

// Retorna palavras que o aluno ainda não aprendeu (baseado em IDs salvos)
export function getUnlearnedWords(learnedIds: string[], count: number = 10): ParetoWord[] {
  const unlearned = PARETO_VOCAB.filter(w => !learnedIds.includes(w.id));
  return shuffleWords(unlearned).slice(0, count);
}
